export function getFormValue(formData: FormData, name: string, fallback = "None") {
  const value = formData.get(name);

  return typeof value === "string" && value.length > 0 ? value : fallback;
}

export function getFormValues(formData: FormData, name: string) {
  return formData.getAll(name).filter((value): value is string => typeof value === "string");
}

import { getFormValue } from "../../form/examples/form-value";
import * as React from "react";
import type { QuestionnaireItemStatus } from "@shadcn/react/questionnaire";
import { toast } from "@/registry/erbium/ui/toast";

import {
  Questionnaire,
  QuestionnaireActions,
  QuestionnaireChoice,
  QuestionnaireChoices,
  QuestionnaireDescription,
  QuestionnaireError,
  QuestionnaireItem,
  QuestionnaireNext,
  QuestionnairePrevious,
  QuestionnaireStepIndicator,
  QuestionnaireSubmit,
  QuestionnaireTitle,
} from "@/registry/erbium/ui/questionnaire";

const items = [
  { name: "permission", required: true },
  { name: "verification", required: true },
] as const;

type ItemName = "permission" | "verification";

export function QuestionnaireNavigationState() {
  const [item, setItem] = React.useState<ItemName>("permission");

  const [statuses, setStatuses] = React.useState<Record<ItemName, QuestionnaireItemStatus>>({
    permission: "unanswered",
    verification: "unanswered",
  });

  const unanswered = statuses[item] === "unanswered";

  function setStatus(name: ItemName, status: QuestionnaireItemStatus) {
    setStatuses((current) => ({ ...current, [name]: status }));
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    const formData = new FormData(event.currentTarget);

    toast.add({
      description: `Permission: ${getFormValue(formData, "permission")} · Verification: ${getFormValue(formData, "verification")}`,
      title: "Permissions saved",
    });
  }

  return (
    <Questionnaire
      className="mx-auto max-w-md"
      item={item}
      items={items}
      onItemChange={(nextItem) => {
        setItem(nextItem as ItemName);
      }}
      onSubmit={handleSubmit}
    >
      <QuestionnaireStepIndicator />

      <QuestionnaireItem
        name="permission"
        required
        onStatusChange={(status) => {
          setStatus("permission", status);
        }}
      >
        <QuestionnaireTitle>What may the agent modify?</QuestionnaireTitle>
        <QuestionnaireDescription>
          Next is intentionally disabled until an answer is selected.
        </QuestionnaireDescription>
        <QuestionnaireChoices>
          <QuestionnaireChoice value="files">Project files</QuestionnaireChoice>
          <QuestionnaireChoice value="tests">Project files and tests</QuestionnaireChoice>
          <QuestionnaireChoice value="config">Files, tests, and configuration</QuestionnaireChoice>
        </QuestionnaireChoices>
        <QuestionnaireError />
      </QuestionnaireItem>

      <QuestionnaireItem
        name="verification"
        required
        onStatusChange={(status) => {
          setStatus("verification", status);
        }}
      >
        <QuestionnaireTitle>What must pass before completion?</QuestionnaireTitle>
        <QuestionnaireChoices>
          <QuestionnaireChoice value="tests">Tests</QuestionnaireChoice>
          <QuestionnaireChoice value="types">Tests and types</QuestionnaireChoice>
          <QuestionnaireChoice value="all">Tests, types, and visual QA</QuestionnaireChoice>
        </QuestionnaireChoices>
        <QuestionnaireError />
      </QuestionnaireItem>

      <QuestionnaireActions>
        <QuestionnairePrevious />
        <QuestionnaireNext
          className="data-[status=unanswered]:opacity-50"
          disabled={unanswered}
          variant="secondary"
        >
          Next
        </QuestionnaireNext>
        <QuestionnaireSubmit disabled={unanswered}>Save permissions</QuestionnaireSubmit>
      </QuestionnaireActions>
    </Questionnaire>
  );
}

import { QuestionnaireNavigationState } from "../examples/questionnaire-navigation-state";

const Example = () => <QuestionnaireNavigationState />;

export default Example;
